using System;using System.IO;using UnityEngine;
public sealed class KeyConfigStore {public readonly string Path;public KeyConfigStore(string path){Path=System.IO.Path.GetFullPath(path);}public KeyConfigProfile Load(KeyConfigProfile defaults,out string status){try{if(!File.Exists(Path)){status="既定値（保存ファイルなし）";return defaults.Copy();}var info=new FileInfo(Path);if(info.Length>131072)throw new Exception("File too large");var profile=JsonUtility.FromJson<KeyConfigProfile>(File.ReadAllText(Path));if(profile==null||!profile.Validate(out var error))throw new Exception("Unsupported/invalid data");status="保存設定を読み込みました";return profile;}catch(Exception e){status="保存設定を読めないため既定値: "+e.GetType().Name;return defaults.Copy();}}
 public bool Save(KeyConfigProfile profile,out string error){error=null;if(profile==null||!profile.Validate(out error))return false;string temp=Path+".tmp";try{Directory.CreateDirectory(System.IO.Path.GetDirectoryName(Path));File.WriteAllText(temp,JsonUtility.ToJson(profile,true));if(File.Exists(Path))File.Replace(temp,Path,Path+".bak");else File.Move(temp,Path);return true;}catch(Exception e){error="保存できません: "+e.GetType().Name;return false;}}
}
